/// <summary>
/// Class used to handle dynamic behavior of dailog during the service execution. 
/// </summary>
internal final class METUpdateStockAvailabilityUIBuilder extends SysOperationAutomaticUIBuilder
{
    private DialogField itemIdDialogField;
    private DialogField siteIdDialogField;


}

Method.Source:
/// <summary>
/// Method used to handle the behavior of the dialog controls.
/// </summary>
public void postBuild()
{
    super();
    METUpdateStockAvailabilityContract contract = this.dataContractObject() as METUpdateStockAvailabilityContract;
    if (contract.parmIsPeriodicExecution() == false)
    {
        siteIdDialogField = this.bindInfo().getDialogField(contract, methodStr(METUpdateStockAvailabilityContract, parmInventSiteId));
        siteIdDialogField.allowEdit(false);
        itemIdDialogField = this.bindInfo().getDialogField(contract, methodStr(METUpdateStockAvailabilityContract, parmItemId));
        itemIdDialogField.allowEdit(false);
    }
}
